import java.io.IOException;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String S = br.readLine();
        String T = br.readLine();

        String ans = "YES";
        int j = 0;
        for (int i = T.length() - 1; i >= 0; i--) {
            if (j >= S.length() || T.charAt(i) != S.charAt(j)) {
                ans = "NO";
                break;
            }
            j++;
        }
        // Handle case where S is longer than T (loop finishes but j < S.length)
        // The original JS code returns YES in this case because the loop condition is i >= 0.
        // However, typically "reverse equals" implies same length.
        // Sticking strictly to JS logic: loop runs T.length times.
        // If S is longer, JS accesses S[j] which is undefined, comparison fails -> NO.
        // Wait, JS: S[j] for j >= S.length is undefined. T[i] !== undefined -> true -> NO.
        // My Java check `j >= S.length()` handles this correctly.

        System.out.println(ans);
    }
}

